# This file generates research instructions only; it performs no scientific calculation.
assert len(rows)==125, len(rows)
for r in rows:
    assert len(r['steps'])>=4 and len(r['checks'])>=2
    assert all(int(x[2:])<int(r['id'][2:]) for x in r['depends_on']), (r['id'],r['depends_on'])
    assert all(Path(p).is_file() for p in r['sources']),r['id']
assert {g:sum(r['group']==g for r in rows) for g in groups}=={g:25 for g in groups}
OUT.write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
print('Wrote',len(rows),'tasks to',OUT)
for g in groups:
    subset=[r for r in rows if r['group']==g]
    sizes=[len(re.findall(r'\S+', ' '.join([r['title'],r['principle'],r['math'],r['inputs'],*r['steps'],*r['checks'],r['completion']]))) for r in subset]
    print(g,len(subset),'words',min(sizes),max(sizes),'mean',round(sum(sizes)/len(sizes),1))
